/* Types */
/**
 *  What a route matches. Process matchers use the executable name or full path. The domain matcher
 *  matches a domain and its subdomains for every application, so it cannot separate applications.
 */
export type AppMatcher =
  | { kind: 'process_name'; name: string }
  | { kind: 'process_path'; path: string }
  | { kind: 'domain_suffix'; suffix: string }

/**
 *  An application or subsystem route. Routes are independent objects; each one lists what it covers
 *  and where that traffic goes.
 */
export type AppRoute = {
  schema_version: number
  id: string
  name: string
  matchers: AppMatcher[]
  target: RouteTarget
  enabled: boolean
  /**
   *  Resolver for this route's domain matchers, as a DoH URL or an IP address. It is only valid with
   *  domain matchers, and it applies to every application that resolves those domains.
   */
  nameserver?: string | null
}

export type AutoProxyWire = {
  enable: boolean
  url: string
}

export type Binding = {
  id: string
  plugin_id: string
  target_id: string
  source: Source
  priority: number
  enabled: boolean
  config: unknown
  orphan?: boolean
  disappeared_at?: string | null
}

/**  One plugin listed by a catalog. `sha256` covers the exact `.c5p` bytes. */
export type CatalogEntry = {
  id: string
  version: string
  name: string
  description: string
  file: string
  sha256: string
}

export type ChainActivation = {
  selection_persisted: boolean
}

export type ChainNodeOption = {
  reference: NodeRef
  display_name: string
  kind: string
  server: string
  port: number
  source_name: string | null
}

/**  One detection or test outcome. `status` is one of healthy, drift, warning, failed, tested. */
export type ChainSample = {
  chain_id: string
  measured_at: string
  status: string
  exit_ip: string | null
  delay_ms: number | null
}

export type ChainTestResult = {
  delay_ms: number
  group_name: string
}

export type ChainWorkspace = {
  profile_id: string | null
  chains: ProxyChain[]
  pools: NodePool[]
  nodes: ChainNodeOption[]
  policy_groups: string[]
}

export type CheckStatus = 'pass' | 'fail' | 'unsupported'

export type Clash5IdentityStatus = {
  recovery_mode: boolean
  pending_rebinds: number
}

export type ClashInfo = {
  /**  clash core port */
  mixed_port: number
  socks_port: number
  port: number
  /**  same as `external-controller` */
  server: string
  /**  clash secret */
  secret: string | null
}

/**  Structured command failure returned to the frontend. */
export type CommandFailure =
  | CommandFailure_Serialize
  | CommandFailure_Deserialize

/**  Structured command failure returned to the frontend. */
export type CommandFailure_Deserialize = {
  /**  Stable frontend identifier, when classified. */
  code: string | null
  /**  Human-readable diagnostic detail. */
  detail: string
  /**  Requested operation when known by the command. */
  operation: FailedOperation | null
}

/**  Structured command failure returned to the frontend. */
export type CommandFailure_Serialize = {
  /**  Stable frontend identifier, when classified. */
  code?: string | null
  /**  Human-readable diagnostic detail. */
  detail: string
  /**  Requested operation when known by the command. */
  operation?: FailedOperation | null
}

export type ConfigProvenance =
  | { kind: 'profile' }
  | { kind: 'plugin'; plugin_id: string; binding_id: string; priority: number }

/**  Why the Core is not running, kept until a Core starts again. */
export type CoreFailure =
  | { kind: 'startFailed'; detail: string }
  | { kind: 'serviceCoreStopped'; detail: string }

export type CoreUpgradeReport = {
  /**  False when the managed core was already at the latest version. */
  upgraded: boolean
  from: string
  to: string
}

export type DelayHistoryContract = {
  time: string
  delay: number
}

export type DnsCheckReport = {
  resolvers: DnsResolvers
  checks: LeakCheck[]
  checked_at: string
}

export type DnsOverrideOutcome =
  | { status: 'applied' }
  | { status: 'confirmation_required'; source: string }

export type DnsResolvers = {
  nameserver: string[]
  fallback: string[]
  default_nameserver: string[]
  listen: string | null
}

export type DnsSample = {
  domain: string
  answer: string | null
  error: string | null
  duration_ms: number
}

/**  Same wire shape as the updater plugin's JS `DownloadEvent`. */
export type DownloadEvent =
  | {
      event: 'Started'
      data: {
        contentLength: number | null
      }
    }
  | {
      event: 'Progress'
      data: {
        chunkLength: number
      }
    }
  | { event: 'Finished' }

export type ExitIpResult =
  | { status: 'disabled' }
  | { status: 'healthy'; observation: ExitObservation }
  /**  The exit address differs from the chain's pinned address. Reported under the warn policy. */
  | { status: 'drift'; observation: ExitObservation; pinned_ip: string }
  | { status: 'warning'; code: string }
  | {
      status: 'switched'
      fallback_chain_id: string
      observation: ExitObservation
      selection_persisted: boolean
    }

export type ExitObservation = {
  ip: string
  elapsed_ms: number
}

export type ExitPolicy =
  | { mode: 'warn' }
  | { mode: 'switch'; fallback_chain_id: string }

/**  Operation associated with a pending failure. */
export type FailedOperation =
  | 'systemProxyEnable'
  | 'systemProxyDisable'
  | 'systemProxyRestore'
  | 'systemProxyGuard'

export type Hop =
  /**  One node, used as this hop. */
  | { kind: 'node'; node: NodeRef }
  /**  A pool, used as this hop. Traffic uses whichever member the latency probe currently prefers. */
  | { kind: 'pool'; pool_id: string }

